const fs=require('fs'),P='data/xauusd-m5-dukascopy.json';const M=JSON.parse(fs.readFileSync(P,'utf8')).map(x=>({t:+(x.timestamp??x.time),o:+(x.open??x.o),h:+(x.high??x.h),l:+(x.low??x.l),c:+(x.close??x.c)})).filter(x=>[x.t,x.o,x.h,x.l,x.c].every(Number.isFinite)).sort((a,b)=>a.t-b.t);
function ema(v,p){let o=Array(v.length).fill(NaN),e=v[0],k=2/(p+1);for(let i=0;i<v.length;i++){if(i)e=v[i]*k+e*(1-k);if(i>=p-1)o[i]=e}return o}function atr(c,p=14){let o=Array(c.length).fill(NaN),s=0;for(let i=1;i<c.length;i++){let tr=Math.max(c[i].h-c[i].l,Math.abs(c[i].h-c[i-1].c),Math.abs(c[i].l-c[i-1].c));s+=tr;if(i>p){let j=i-p,old=Math.max(c[j].h-c[j].l,Math.abs(c[j].h-c[j-1].c),Math.abs(c[j].l-c[j-1].c));s-=old}if(i>=p)o[i]=s/p}return o}function h1(){let a=[],z;for(const x of M){let d=new Date(x.t),t=Date.UTC(d.getUTCFullYear(),d.getUTCMonth(),d.getUTCDate(),d.getUTCHours());if(!z||z.t!==t){z={t,o:x.o,h:x.h,l:x.l,c:x.c};a.push(z)}else{z.h=Math.max(z.h,x.h);z.l=Math.min(z.l,x.l);z.c=x.c}}return a}
const H=h1(),ME=ema(M.map(x=>x.c),20),MA=atr(M),HC=H.map(x=>x.c),H20=ema(HC,20),H50=ema(HC,50),HA=atr(H);let hp=0,HI=[];for(let i=0;i<M.length;i++){while(hp+1<H.length&&H[hp+1].t<=M[i].t)hp++;HI[i]=Math.max(0,hp-1)}
const BASE={sep:.10,body:.65,pos:.72,range:2,dist:1.5,risk:1.35,block:[2,6,12,18,20,22],buyBlock:[3,16]};const Q={sep:.10,body:.65,pos:.76,range:2,dist:1.1,risk:1.35,block:[2,6,12,18,19,20,22],buyBlock:[3,16,17]};
function run(q){let out=[],p=null;for(let i=60;i<M.length-1;i++){if(p){let b=M[i],sl=p.s==='BUY'?b.l<=p.sl:b.h>=p.sl,tp=p.s==='BUY'?b.h>=p.tp:b.l<=p.tp;if(sl||tp||i-p.ei+1>=10){let px=sl?p.sl:tp?p.tp:b.c,r=(p.s==='BUY'?px-p.en:p.en-px)/p.risk;out.push({t:M[p.si].t,r,s:p.s,h:new Date(M[p.si].t).getUTCHours()});p=null}if(p)continue}let h=HI[i],hr=new Date(M[i].t).getUTCHours();if(q.block.includes(hr)||h<52)continue;if(![ME[i],MA[i],H20[h],H50[h],HA[h],H20[h-2]].every(Number.isFinite)||!(MA[i]>0&&HA[h]>0))continue;let sep=Math.abs(H20[h]-H50[h])/HA[h];if(sep<q.sep)continue;let bull=HC[h]>H20[h]&&H20[h]>H50[h]&&H20[h]>H20[h-2],bear=HC[h]<H20[h]&&H20[h]<H50[h]&&H20[h]<H20[h-2];if(!bull&&!bear)continue;let hi=-Infinity,lo=Infinity;for(let j=i-3;j<i;j++){hi=Math.max(hi,M[j].h);lo=Math.min(lo,M[j].l)}let rg=M[i].h-M[i].l,body=Math.abs(M[i].c-M[i].o);if(!rg||body/MA[i]<q.body||rg/MA[i]>q.range)continue;let cp=(M[i].c-M[i].l)/rg;if(Math.abs(M[i].c-ME[i])/MA[i]>q.dist)continue;let buy=bull&&M[i].c>hi&&cp>=q.pos&&M[i].c>ME[i],sell=bear&&M[i].c<lo&&cp<=1-q.pos&&M[i].c<ME[i];if(!buy&&!sell)continue;let side=buy?'BUY':'SELL';if(side==='BUY'&&q.buyBlock.includes(hr))continue;let en=M[i+1].o,sw=side==='BUY'?Math.min(M[i].l,M[i-1].l):Math.max(M[i].h,M[i-1].h),risk=Math.max(MA[i]*.65,Math.abs(en-sw));if(risk>MA[i]*q.risk)continue;let rr=side==='BUY'?.85:.8;p={s:side,en,risk,sl:side==='BUY'?en-risk:en+risk,tp:side==='BUY'?en+risk*rr:en-risk*rr,ei:i+1,si:i}}return out}
function S(a){let gp=0,gl=0,w=0,e=0,pk=0,dd=0,ls=0,mx=0;for(const x of a){e+=x.r;if(x.r>0){w++;gp+=x.r;ls=0}else if(x.r<0){gl-=x.r;ls++;mx=Math.max(mx,ls)}pk=Math.max(pk,e);dd=Math.max(dd,pk-e)}return{n:a.length,wr:a.length?100*w/a.length:0,pf:gl?gp/gl:(gp?Infinity:0),net:e,dd,ls:mx}}const F=s=>`T${s.n} WR${s.wr.toFixed(1)} PF${s.pf===Infinity?'∞':s.pf.toFixed(2)} N${s.net>=0?'+':''}${s.net.toFixed(2)}R DD${s.dd.toFixed(2)} LS${s.ls}`;
