const all=S(C),recent=S(C.filter(x=>x.t>=hi-90*86400000)),pass=all.n>=160&&all.wr>=64.5&&all.pf>=1.5&&all.dd<=S(B).dd&&good>=4&&recent.n>=25&&recent.pf>=1.15;console.log(`\nFINAL GATE: ${pass?'✅ PASS':'❌ FAIL'} | folds=${good}/5 | 90D ${F(recent)}`);console.log(pass?'Candidate may proceed to live-code update.':'Keep Q1297 live; do not promote Q2680.');
